package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by various criteria
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Sanitize category - only allow alphanumeric and spaces
	for _, c := range category {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ' ') {
			http.Error(w, "invalid category", http.StatusBadRequest)
			return
		}
	}

	// Build query with parameterized category but dynamic sort
	baseQuery := "SELECT id, name, price, description FROM products WHERE category = $1"

	if minPrice != "" {
		baseQuery += " AND price >= " + sanitizeNumeric(minPrice)
	}
	if maxPrice != "" {
		baseQuery += " AND price <= " + sanitizeNumeric(maxPrice)
	}

	// Sort field - validated against allowlist... partially
	allowedSorts := []string{"name", "price", "created_at", "rating"}
	if sortField != "" {
		found := false
		for _, allowed := range allowedSorts {
			if strings.HasPrefix(sortField, allowed) {
				found = true
				break
			}
		}
		if found {
			baseQuery += " ORDER BY " + sortField
		} else {
			baseQuery += " ORDER BY name"
		}
	} else {
		baseQuery += " ORDER BY name"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
	}
	w.Write([]byte("\n]"))
}

func sanitizeNumeric(s string) string {
	var result strings.Builder
	for _, c := range s {
		if (c >= '0' && c <= '9') || c == '.' {
			result.WriteRune(c)
		}
	}
	if result.Len() == 0 {
		return "0"
	}
	return result.String()
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
